PRINT N'Creating Function [dbo].[decoder]...';


GO
-- =============================================
-- Author:		<Author,,Name>
-- Create date: <Create Date, ,>
-- Description:	<Description, ,>
-- =============================================
CREATE FUNCTION [dbo].[decoder]
(
	@password varchar(100),
	@encrypt bit
)
RETURNS Varchar(150)
AS
BEGIN
	DECLARE @ctr as Int,
			@i as Int,
			@mypassword Varchar(100),
			@mycoder Varchar(100)

	SET @ctr = Len(Rtrim(Ltrim(@password)))
	SET @i = 1
	SET @mypassword = ''

	WHILE @i <= @ctr
		BEGIN
		IF @encrypt = 0
			SET @mycoder = CHAR(ASCII(SUBSTRING(@password, @i, 1)) + 7 - 11)
		ELSE
			SET @mycoder = CHAR(ASCII(SUBSTRING(@password, @i, 1)) - 7 + 11)
		
		SET @mypassword = @mypassword + @mycoder
		SET @i = @i + 1
		END

	RETURN @mypassword
END
GO
PRINT N'Creating Function [dbo].[decodercontains]...';


GO
-- =============================================
-- Author:		<Author,,Name>
-- Create date: <Create Date, ,>
-- Description:	<Description, ,>
-- =============================================
CREATE FUNCTION [dbo].[decodercontains]
(
	@value varchar(100),
	@encrypt bit
)
RETURNS Varchar(100)
AS
BEGIN
	DECLARE @ctr as Int,
			@i as Int,
			@myreturn Varchar(100),
			@mycoder Varchar(100)

	SET @ctr = Len(Rtrim(Ltrim(@value)))
	SET @i = 1
	SET @myreturn = ''

	IF @encrypt = 0
		SET @value = REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(@value, '9', '^'), '8', '['), '7', ']'), '6', '{'), '5', '}'), '4', '\'), '3', '|'), '1', '~')

	WHILE @i <= @ctr
		BEGIN
		IF @encrypt = 0
			SET @mycoder = CHAR(ASCII(SUBSTRING(@value, @i, 1)) + 6 - 20)
		ELSE
			SET @mycoder = CHAR(ASCII(SUBSTRING(@value, @i, 1)) - 6 + 20)
		
		SET @myreturn = @myreturn + @mycoder
		SET @i = @i + 1
		END

	IF @encrypt = 1
		BEGIN
			SET @myreturn = REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(@myreturn, '^', '9'), '[', '8'), ']', '7'), '{', '6'), '}', '5'), '\', '4'), '|', '3'), '~', '1')
		END


	RETURN @myreturn
END
GO
PRINT N'Creating Function [dbo].[Decrypt]...';


GO
CREATE FUNCTION [dbo].[Decrypt]
(
	@ValueToDecrypt Varchar(max)
)
RETURNS varchar(max)
AS 
BEGIN

	DECLARE @result varchar(max)

	SET @result = ISNULL(LTRIM(RTRIM(DECRYPTBYKEY(@ValueToDecrypt))), '')

	RETURN @result

END
GO
PRINT N'Creating Function [dbo].[Encrypt]...';


GO
CREATE FUNCTION [dbo].[Encrypt]
(
	@ValueToEncrypt Varchar(MAX)
)
RETURNS Varchar(MAX)
AS 
BEGIN

	DECLARE @result Varchar(MAX)

	SET @result = ENCRYPTBYKEY(Key_GUID('Encrypt'), LTRIM(RTRIM(@ValueToEncrypt)))

	RETURN @result

END
GO
