CREATE   PROCEDURE [dbo].[sp_getadvisorysettings] --1, 0, 0, 0
	-- Add the parameters for the stored procedure here
	
	@datecreatedfrom	Smalldatetime,
	@datecreatedto		Smalldatetime,
	@pageno				Int,
	@rowctr				Int,
	@rowcount			Int = 0 OUTPUT

AS
BEGIN
	-- SET NOCOUNT ON added to prevent extra result sets from
	-- interfering with SELECT statements.
	SET NOCOUNT ON;

	DECLARE @ldatecreatedfrom	Smalldatetime	= @datecreatedfrom,
			@ldatecreatedto		Smalldatetime	= @datecreatedto,
			@lpageno			Int				= @pageno,
			@lrowctr			Int				= @rowctr

    -- Insert statements for procedure here
	SELECT @rowcount = COUNT(1)
	FROM tblcompanyadvisorysettings a WITH(NOLOCK)
	WHERE ((@ldatecreatedfrom = '1/1/1900' AND a.detno <> 0) OR ((@ldatecreatedfrom <> '1/1/1900' AND @ldatecreatedto <> '1/1/1900')
			AND (CAST(a.datecreated  AS DATE) >= CAST(@ldatecreatedfrom AS DATE) AND CAST(a.datecreated  AS DATE) <= CAST(@ldatecreatedto AS DATE))))
	OPTION(RECOMPILE)

	If @pageno <= 0 or @rowctr <= 0
		BEGIN
			SELECT a.detno, a.durationfrom, 
			a.durationto, a.postadvisorytohr, a.datecreated,
			message = ISNULL(LTRIM(RTRIM(a.message)),''),
			a.createdby,createdbyname = ISNULL(LTRIM(RTRIM(b.username)),'')
			FROM tblcompanyadvisorysettings a
			OUTER APPLY (SELECT username FROM tblusers b WITH(NOLOCK) WHERE a.createdby = b.userno) b
			WHERE ((@ldatecreatedfrom = '1/1/1900' AND a.detno <> 0) OR ((@ldatecreatedfrom <> '1/1/1900' AND @ldatecreatedto <> '1/1/1900')
					AND (CAST(a.datecreated  AS DATE) >= CAST(@ldatecreatedfrom AS DATE) AND CAST(a.datecreated  AS DATE) <= CAST(@ldatecreatedto AS DATE))))
			ORDER BY a.datecreated
		END
	ELSE
		BEGIN
			SELECT a.detno, a.durationfrom, 
			a.durationto, a.postadvisorytohr, a.datecreated,
			message = ISNULL(LTRIM(RTRIM(a.message)),''),
			a.createdby,createdbyname = ISNULL(LTRIM(RTRIM(b.username)),'')
			FROM tblcompanyadvisorysettings a
			OUTER APPLY (SELECT username FROM tblusers b WITH(NOLOCK) WHERE a.createdby = b.userno) b
			WHERE ((@ldatecreatedfrom = '1/1/1900' AND a.detno <> 0) OR ((@ldatecreatedfrom <> '1/1/1900' AND @ldatecreatedto <> '1/1/1900')
					AND (CAST(a.datecreated  AS DATE) >= CAST(@ldatecreatedfrom AS DATE) AND CAST(a.datecreated  AS DATE) <= CAST(@ldatecreatedto AS DATE))))
			ORDER BY a.datecreated
			OFFSET ((@lpageno - 1) * @lrowctr) ROWS
			FETCH NEXT @lrowctr ROWS ONLY
			OPTION(RECOMPILE)		
		END
	
END
GO
