CREATE   PROCEDURE [dbo].[sp_getwebcompanydisplaysettings] --1, 0, 0, 0
	-- Add the parameters for the stored procedure here
	
	@compcode			Int,
	@datecreatedfrom	Smalldatetime,
	@datecreatedto		Smalldatetime,
	@pageno				Int,
	@rowctr				Int,
	@rowcount			Int = 0 OUTPUT

AS
BEGIN
	-- SET NOCOUNT ON added to prevent extra result sets from
	-- interfering with SELECT statements.
	SET NOCOUNT ON;

	DECLARE 
			@lcompcode			Int				= @compcode,
			@ldatecreatedfrom	Smalldatetime	= @datecreatedfrom,
			@ldatecreatedto		Smalldatetime	= @datecreatedto,
			@lpageno			Int				= @pageno,
			@lrowctr			Int				= @rowctr

    -- Insert statements for procedure here
	SELECT @rowcount = COUNT(1)
	FROM tblcompanydisplaysettings a WITH(NOLOCK)
	WHERE ((@lcompcode = 0 AND a.detno <> 0) OR (@lcompcode <> 0 AND a.compcode = @lcompcode))
		  AND ((@ldatecreatedfrom = '1/1/1900' AND a.detno <> 0) OR ((@ldatecreatedfrom <> '1/1/1900' AND @ldatecreatedto <> '1/1/1900')
			AND (CAST(a.datecreated  AS DATE) >= CAST(@ldatecreatedfrom AS DATE) AND CAST(a.datecreated  AS DATE) <= CAST(@ldatecreatedto AS DATE))))
	OPTION(RECOMPILE)

	If @pageno <= 0 or @rowctr <= 0
		BEGIN
				SELECT a.detno, a.compcode, a.datecreated, a.showdatehired, a.showemployeeno, a.showmemberid,
					companyname = ISNULL(dbo.decoder(b.ldflog,0), ''),
					contractno = ISNULL(b.contractno, ''),
					encodedbyname = ISNULL(c.username, '')
	
				FROM tblcompanydisplaysettings a WITH(NOLOCK)
				OUTER APPLY (SELECT ldflog, contractno FROM tblcompany b WITH(NOLOCK) WHERE a.compcode = b.compcode) b
				OUTER APPLY (SELECT username FROM tblusers c WITH(NOLOCK) WHERE a.createdby = c.userno) c
				WHERE ((@lcompcode = 0 AND a.detno <> 0) OR (@lcompcode <> 0 AND a.compcode = @lcompcode))
					AND ((@ldatecreatedfrom = '1/1/1900' AND a.detno <> 0) OR ((@ldatecreatedfrom <> '1/1/1900' AND @ldatecreatedto <> '1/1/1900')
						AND (CAST(a.datecreated  AS DATE) >= CAST(@ldatecreatedfrom AS DATE) AND CAST(a.datecreated  AS DATE) <= CAST(@ldatecreatedto AS DATE))))
			ORDER BY a.datecreated
		END
	ELSE
		BEGIN
			    SELECT a.detno, a.compcode, a.datecreated, a.showdatehired, a.showemployeeno, a.showmemberid,
					companyname = ISNULL(dbo.decoder(b.ldflog,0), ''),
					contractno = ISNULL(b.contractno, ''),
					encodedbyname = ISNULL(c.username, '')
	
				FROM tblcompanydisplaysettings a WITH(NOLOCK)
				OUTER APPLY (SELECT ldflog, contractno FROM tblcompany b WITH(NOLOCK) WHERE a.compcode = b.compcode) b
				OUTER APPLY (SELECT username FROM tblusers c WITH(NOLOCK) WHERE a.createdby = c.userno) c
				WHERE ((@lcompcode = 0 AND a.detno <> 0) OR (@lcompcode <> 0 AND a.compcode = @lcompcode))
					AND ((@ldatecreatedfrom = '1/1/1900' AND a.detno <> 0) OR ((@ldatecreatedfrom <> '1/1/1900' AND @ldatecreatedto <> '1/1/1900')
						AND (CAST(a.datecreated  AS DATE) >= CAST(@ldatecreatedfrom AS DATE) AND CAST(a.datecreated  AS DATE) <= CAST(@ldatecreatedto AS DATE))))
			ORDER BY a.datecreated
			OFFSET ((@lpageno - 1) * @lrowctr) ROWS
			FETCH NEXT @lrowctr ROWS ONLY
			OPTION(RECOMPILE)		
		END
	
END
