CREATE   PROCEDURE [dbo].[sp_saveadvisorysettings]
	-- Add the parameters for the stored procedure here
	
	@detno				Int,
	@durationfrom		Smalldatetime,
	@durationto			Smalldatetime,
	@message			Varchar(240),
	@postadvisorytohr	Bit,
	@createdby			Int

AS
BEGIN
	-- SET NOCOUNT ON added to prevent extra result sets from
	-- interfering with SELECT statements.
	SET NOCOUNT ON;

	DECLARE @ldetno				Int				= @detno,
			@ldurationfrom		Smalldatetime	= @durationfrom,
			@ldurationto		Smalldatetime	= @durationto,
			@lmessage			Varchar(240)	= @message,
			@lpostadvisorytohr	Bit				= @postadvisorytohr,
			@lcreatedby			Int				= @createdby

    -- Insert statements for procedure here
		IF @ldetno = NULL OR @ldetno = 0  
            BEGIN  
				INSERT INTO tblcompanyadvisorysettings(createdby, datecreated) 
				VALUES( @lcreatedby, GETDATE()) 
				SELECT @ldetno = @@IDENTITY 
            END  
	
		UPDATE tblcompanyadvisorysettings  
		SET message				= @lmessage,
			durationfrom		= @ldurationfrom,
			durationto			= @ldurationto,
			postadvisorytohr	= @lpostadvisorytohr
		WHERE detno = @ldetno
		OPTION(RECOMPILE)

		SELECT @ldetno AS detno

END
GO
