		SELECT @ldetno AS detno
END
GO
PRINT N'Creating Procedure [dbo].[sp_updatememberalternateemail]...';


GO

-- =============================================
-- Author:		<Author,,Name>
-- Create date: <Create Date,,>
-- Description:	<Description,,>
-- =============================================
CREATE PROCEDURE [dbo].[sp_updatememberalternateemail]
	-- Add the parameters for the stored procedure here
	
	@membercode		Int,
	@emailaddress	Varchar(150),
	@notifyloa		Bit

AS
BEGIN
	-- SET NOCOUNT ON added to prevent extra result sets from
	-- interfering with SELECT statements.
	SET NOCOUNT ON;

    DECLARE @lmembercode	Int				= @membercode,
			@lemailaddress	Varchar(150)	= @emailaddress,
			@lnotifyloa		Bit				= @notifyloa

	EXEC sp_opensymmetric

	UPDATE tblmemberdetails
	SET alternateemail	= dbo.Encrypt(@lemailaddress),
		notifyloa		= @lnotifyloa
	WHERE membercode = @lmembercode
	OPTION(RECOMPILE)

	EXEC sp_closesymmetric

	SELECT @lmembercode AS membercode

END
GO
PRINT N'Creating Procedure [dbo].[sp_updateportaluploadenrollmentperiodv2]...';


GO


-- =============================================
-- Author:		<Author,,Name>
-- Create date: <Create Date,,>
-- Description:	<Description,,>
-- =============================================
CREATE PROCEDURE [dbo].[sp_updateportaluploadenrollmentperiodv2] 
	-- Add the parameters for the stored procedure here
	
	@portalcode				Int,
	@batchcode				Int,
	@enrollmentperiodfrom	SmallDateTime,
	@enrollmentperiodto		SmallDateTime,
	@enrollmentperiodsamewithaccount	Bit

AS
BEGIN
	-- SET NOCOUNT ON added to prevent extra result sets from
	-- interfering with SELECT statements.
	SET NOCOUNT ON;
	DECLARE @lportalcode			Int				= @portalcode,
			@lbatchcode				Int				= @batchcode,
			@lenrollmentperiodfrom	SmallDateTime	= @enrollmentperiodfrom,
			@lenrollmentperiodto	SmallDateTime	= @enrollmentperiodto,
			@lenrollmentperiodsamewithaccount	Bit	= @enrollmentperiodsamewithaccount

    -- Insert statements for procedure here.
		UPDATE tblportalupload
		SET enrollmentperiodfrom			= @lenrollmentperiodfrom,
			enrollmentperiodto				= @lenrollmentperiodto,
			enrollmentperiodsamewithaccount = @lenrollmentperiodsamewithaccount
		WHERE portalcode = @lportalcode

		UPDATE a
		SET enrollmentperiodfrom	= @lenrollmentperiodfrom,
			enrollmentperiodto		= @lenrollmentperiodto
		FROM tblmembers  a
		OUTER APPLY (SELECT membercode FROM tblmemberuploaddetails b WHERE b.batchcode = @lbatchcode) b
		WHERE b.membercode = a.membercode

	Select @lportalcode as portalcode
	OPTION(RECOMPILE)

END
GO
PRINT N'Creating Procedure [dbo].[sp_uploadmemmapmemberdetails]...';


GO

-- =============================================
-- Author:		<Author,,Name>
-- Create date: <Create Date,,>
-- Description:	<Description,,>
-- =============================================
CREATE   PROCEDURE [dbo].[sp_uploadmemmapmemberdetails]
	@portalcode		INT,
	@compcode		INT
AS
BEGIN
	-- SET NOCOUNT ON added to prevent extra result sets from
	-- interfering with SELECT statements.
	SET NOCOUNT ON;

	DECLARE @lportalcode		INT = @portalcode,
			@lcompcode			INT = @compcode,
			@lwithnewmembers	BIT = 0
	
	SELECT @lwithnewmembers = withnewmembers FROM tblportalupload WHERE portalcode = @lportalcode

	IF @lwithnewmembers = 1
		BEGIN
			UPDATE b SET
			membercode = a.membercode,
			memberno = a.memberno,
			topupplan = ISNULL(c.topupplan, 0)
			FROM tblportaluploaddetails a WITH(NOLOCK)
			OUTER APPLY (SELECT membercode, memberno, topupplan FROM tblmemberdetails b WITH(NOLOCK) WHERE a.compcode = b.compcode AND a.dummymemberno = b.dummymemberno) b
			OUTER APPLY (SELECT topupplan FROM tblcompanyclasses c WITH(NOLOCK) WHERE a.compcode = c.compcode AND a.contractcode = c.contractcode AND a.benefitclass = c.classcode) c
			WHERE a.compcode = @lcompcode AND a.portalcode = @lportalcode AND a.uploadtype <> 'R-PD' AND a.uploadtype <> 'A-MP' AND a.uploadtype <> 'F-PD'
		END
END
GO
PRINT N'Creating Procedure [dbo].[sp_getmaswebmemberrequestloav3]...';


GO


-- =============================================
-- Author:		<Author,,Name>
-- Create date: <Create Date,,>
-- Description:	<Description,,>
-- =============================================
CREATE   PROCEDURE [dbo].[sp_getmaswebmemberrequestloav3] --511530, 1, 20
	-- Add the parameters for the stored procedure here

	@membercode		Int,
	@pageno			Int,
	@rowctr			Int,
	@rowcount		Int = 0 Output

AS
BEGIN
	-- SET NOCOUNT ON added to prevent extra result sets from
	-- interfering with SELECT statements.
	SET NOCOUNT ON;

	DECLARE @lmembercode	Int				= @membercode,
			--@dfrom			Smalldatetime	= Getdate()-7,
			--@dto			Smalldatetime	= Getdate()+7,
			@dfrom			Smalldatetime	= DATEADD(DAY, -7, DATEADD(DAY, DATEDIFF(DAY, 0, GETDATE()), 0)),
			@dto			Smalldatetime	= DATEADD(DAY,  7, DATEADD(DAY, DATEDIFF(DAY, 0, GETDATE()), 0)),
			@lpageno		Int				= @pageno,
			@lrowctr		Int				= @rowctr

	-- IMAE-9
	DECLARE @ldependentcount	Int		= 0,
			@lprincipalcontrol	Bit		= 0

	EXEC sp_opensymmetriccompany
	EXEC sp_opensymmetric
	
	SET @ldependentcount = ISNULL((SELECT depcount = Count(membercode) FROM medicalassistance_replicated.dbo.tblmembers a WITH(NOLOCK) 
									WHERE a.principalcode = @lmembercode AND a.classorder = 1), 0)

	IF OBJECT_ID('tempdb..#deps_temp') IS NOT NULL 
	BEGIN 
		DROP TABLE #deps_temp
	END

	CREATE TABLE #deps_temp (membercode Int)

	IF @ldependentcount > 0
		BEGIN
			INSERT INTO #deps_temp (membercode) VALUES (@lmembercode)

			INSERT INTO #deps_temp (membercode)
			SELECT a.membercode
			FROM tblsubscriptionmembers a WITH(NOLOCK) 
			WHERE a.principalcontrol = 1 AND
			a.membercode IN (SELECT membercode FROM medicalassistance_replicated.dbo.tblmembers WITH(NOLOCK) 
							 WHERE principalcode = @lmembercode AND classorder = 1)
			OPTION(RECOMPILE)

			SET @lprincipalcontrol = IIF((SELECT Count(membercode) FROM #deps_temp) > 0, 1, 0)
		END
	 
	SELECT @rowcount = COUNT(1)
	FROM tblrequestloa a WITH(NOLOCK) 
	WHERE 
	(
		(@lprincipalcontrol = 0 AND a.membercode = @lmembercode OR (@ldependentcount > 0 AND a.principalcode = @lmembercode)) OR
		(@lprincipalcontrol = 1 AND EXISTS(SELECT 1 FROM #deps_temp d WHERE d.membercode = a.membercode))
	)
	AND a.dateavailed >= @dfrom AND a.dateavailed < DATEADD(DAY, 1, @dto)
	OPTION(RECOMPILE)

	If @pageno <= 0 or @rowctr <= 0
		SELECT * FROM
		(
			SELECT a.membercode, a.memberno, 
			--a.membername,
			membername = CASE WHEN j.enhancedencryption = 1 THEN dbo.DecryptCompany(k.membername)
								ELSE dbo.Decrypt(i.membername)
								END,
			a.loacode, a.deviceloacode, a.dateavailed, a.providercode, 
			loano = a.loano,
			status = a.status,
			providername = Isnull(b.providername, ''),
			a.doctorcode,
			a.doctorname,
			a.imagectr,
			a.dateposted,
			entryno = right('00000'+CAST(a.loacode AS VARCHAR), CASE WHEN Len(a.loacode) <=5 THEN 5 ELSE Len(a.loacode) END),
			loaconcerndesc = ISNULL(c.description, ''),
			a.loaconcernno,
			streetaddress = ISNULL(b.streetaddress, ''),
			cityname = ISNULL(d.locationname, ''), 
			provincename = ISNULL(e.locationname, ''),
			procedures = a.procedures,
			admittingtext = a.admittingtext,
			a.otherprocedures,
			claimtype = ISNULL(f.claimtype, 0),
			claimtypecode = ISNULL(g.recordcode, ''),
			claimtypedesc = ISNULL(g.description, ''),
			subclaimtype = ISNULL(f.subclaimtype, 0),
			subclaimtypecode = ISNULL(h.recordcode, ''),
			subclaimtypedesc = ISNULL(h.description, '')
			
			FROM tblrequestloa a WITH(NOLOCK)
			LEFT JOIN medicalassistance_replicated.dbo.tblproviders b WITH(NOLOCK) ON a.providercode <> 0 AND a.providercode = b.providercode
			LEFT JOIN tblgentables c WITH(NOLOCK) ON a.loaconcernno <> 0 AND a.loaconcernno = c.detno
			LEFT JOIN medicalassistance_replicated.dbo.tbllocations d WITH(NOLOCK) ON b.citycode <> 0 AND b.citycode = d.locationcode
			LEFT JOIN medicalassistance_replicated.dbo.tbllocations e WITH(NOLOCK) ON b.provincecode <> 0 AND b.provincecode = e.locationcode
			LEFT JOIN medicalassistance_replicated.dbo.tblloas f WITH(NOLOCK) ON a.loano <> '' AND a.loano = f.loano
			LEFT JOIN medicalassistance_replicated.dbo.tblgentables g WITH(NOLOCK) ON f.claimtype <> 0 AND f.claimtype = g.detno AND g.tablename = 'CLAIMS SERVICES'
			LEFT JOIN medicalassistance_replicated.dbo.tblgentables h WITH(NOLOCK) ON f.subclaimtype <> 0 AND f.subclaimtype = h.detno AND h.tablename = 'SUB CLAIM TYPE' AND g.recordcode = h.recordcode
			LEFT JOIN medicalassistance_replicated.dbo.tblmembers i WITH(NOLOCK) ON a.membercode <> 0 AND a.membercode = i.membercode
			LEFT JOIN medicalassistance_replicated.dbo.tblcompany j WITH(NOLOCK) ON i.compcode <> 0 AND i.compcode = j.compcode
			LEFT JOIN medicalassistance_replicated.dbo.tblmembernames k WITH(NOLOCK) ON i.membercode <> 0 AND i.membercode = k.membercode AND j.enhancedencryption = 1
			WHERE 
			(
				(@lprincipalcontrol = 0 AND a.membercode = @lmembercode OR (@ldependentcount > 0 AND a.principalcode = @lmembercode)) OR
				(@lprincipalcontrol = 1 AND EXISTS(SELECT 1 FROM #deps_temp d WHERE d.membercode = a.membercode))
			)
			AND a.dateavailed >= @dfrom AND a.dateavailed < DATEADD(DAY, 1, @dto)
		) result
		ORDER BY dateposted DESC
	ELSE
		SELECT * FROM
		(  
			SELECT a.membercode, a.memberno, 
			--a.membername,
			membername = CASE WHEN j.enhancedencryption = 1 THEN dbo.DecryptCompany(k.membername)
								ELSE dbo.Decrypt(i.membername)
								END,
			a.loacode, a.deviceloacode, a.dateavailed, a.providercode, 
			loano = a.loano,
			status = a.status,
			providername = Isnull(b.providername, ''),
			a.doctorcode,
			a.doctorname,
			a.imagectr,
			a.dateposted,
			entryno = right('00000'+CAST(a.loacode AS VARCHAR), CASE WHEN Len(a.loacode) <=5 THEN 5 ELSE Len(a.loacode) END),
			loaconcerndesc = ISNULL(c.description, ''),
			a.loaconcernno,
			streetaddress = ISNULL(b.streetaddress, ''),
			cityname = ISNULL(d.locationname, ''), 
			provincename = ISNULL(e.locationname, ''),
			procedures = a.procedures,
			admittingtext = a.admittingtext,
			a.otherprocedures,
			claimtype = ISNULL(f.claimtype, 0),
			claimtypecode = ISNULL(g.recordcode, ''),
			claimtypedesc = ISNULL(g.description, ''),
			subclaimtype = ISNULL(f.subclaimtype, 0),
			subclaimtypecode = ISNULL(h.recordcode, ''),
			subclaimtypedesc = ISNULL(h.description, '')
			
			FROM tblrequestloa a WITH(NOLOCK)
			LEFT JOIN medicalassistance_replicated.dbo.tblproviders b WITH(NOLOCK) ON a.providercode <> 0 AND a.providercode = b.providercode
			LEFT JOIN tblgentables c WITH(NOLOCK) ON a.loaconcernno <> 0 AND a.loaconcernno = c.detno
			LEFT JOIN medicalassistance_replicated.dbo.tbllocations d WITH(NOLOCK) ON b.citycode <> 0 AND b.citycode = d.locationcode
			LEFT JOIN medicalassistance_replicated.dbo.tbllocations e WITH(NOLOCK) ON b.provincecode <> 0 AND b.provincecode = e.locationcode
			LEFT JOIN medicalassistance_replicated.dbo.tblloas f WITH(NOLOCK) ON a.loano <> '' AND a.loano = f.loano
			LEFT JOIN medicalassistance_replicated.dbo.tblgentables g WITH(NOLOCK) ON f.claimtype <> 0 AND f.claimtype = g.detno AND g.tablename = 'CLAIMS SERVICES'
			LEFT JOIN medicalassistance_replicated.dbo.tblgentables h WITH(NOLOCK) ON f.subclaimtype <> 0 AND f.subclaimtype = h.detno AND h.tablename = 'SUB CLAIM TYPE' AND g.recordcode = h.recordcode
			LEFT JOIN medicalassistance_replicated.dbo.tblmembers i WITH(NOLOCK) ON a.membercode <> 0 AND a.membercode = i.membercode
			LEFT JOIN medicalassistance_replicated.dbo.tblcompany j WITH(NOLOCK) ON i.compcode <> 0 AND i.compcode = j.compcode
			LEFT JOIN medicalassistance_replicated.dbo.tblmembernames k WITH(NOLOCK) ON i.membercode <> 0 AND i.membercode = k.membercode AND j.enhancedencryption = 1
			WHERE 
			(
				(@lprincipalcontrol = 0 AND a.membercode = @lmembercode OR (@ldependentcount > 0 AND a.principalcode = @lmembercode)) OR
				(@lprincipalcontrol = 1 AND EXISTS(SELECT 1 FROM #deps_temp d WHERE d.membercode = a.membercode))
			)
			AND a.dateavailed >= @dfrom AND a.dateavailed < DATEADD(DAY, 1, @dto)
		) result
		ORDER BY dateposted DESC
		OFFSET ((@lpageno - 1) * @lrowctr) ROWS
		FETCH NEXT @lrowctr ROWS ONLY
		OPTION(RECOMPILE)

	DROP TABLE #deps_temp

	EXEC sp_closesymmetriccompany
	EXEC sp_closesymmetric
END
GO
PRINT N'Update complete.';


